      };

      const result = await photoService.validatePhoto(asset);

      expect(result.valid).toBe(false);
      expect(result.error).toContain('400×400');
    });
  });

  describe('compressPhoto', () => {
    it('should compress photo using expo-image-manipulator', async () => {
      const mockCompressed = { uri: 'file://compressed.jpg' };
      (ImageManipulator.manipulateAsync as jest.Mock).mockResolvedValue(mockCompressed);

      const result = await photoService.compressPhoto('file://test.jpg', 0.8);

      expect(ImageManipulator.manipulateAsync).toHaveBeenCalledWith(
        'file://test.jpg',
        [],
        { compress: 0.8, format: ImageManipulator.SaveFormat.JPEG }
      );
      expect(result).toBe(mockCompressed.uri);
    });

    it('should use default quality of 0.8', async () => {
      const mockCompressed = { uri: 'file://compressed.jpg' };
      (ImageManipulator.manipulateAsync as jest.Mock).mockResolvedValue(mockCompressed);

      await photoService.compressPhoto('file://test.jpg');

      expect(ImageManipulator.manipulateAsync).toHaveBeenCalledWith(
        expect.any(String),
        expect.any(Array),
        expect.objectContaining({ compress: 0.8 })
      );
    });

    it('should throw error on compression failure', async () => {
      (ImageManipulator.manipulateAsync as jest.Mock).mockRejectedValue(
        new Error('Compression failed')
      );

      await expect(photoService.compressPhoto('file://test.jpg')).rejects.toThrow(
        'Failed to compress photo'
      );
    });
  });

  describe('groupPhotosAuto', () => {
    const createMockPhotos = (count: number): PhotoAsset[] => {
      return Array.from({ length: count }, (_, i) => ({
        id: `photo-${i}`,
        uri: `file://photo-${i}.jpg`,
        width: 800,
        height: 600,
      }));
    };

    it('should group photos with 2 per group by default', () => {
      const photos = createMockPhotos(6);
      const groups = photoService.groupPhotosAuto(photos);

      expect(groups).toHaveLength(3);
      expect(groups[0].photos).toHaveLength(2);
      expect(groups[1].photos).toHaveLength(2);
      expect(groups[2].photos).toHaveLength(2);
    });

    it('should respect custom photos per group', () => {
      const photos = createMockPhotos(9);
      const groups = photoService.groupPhotosAuto(photos, 3);

      expect(groups).toHaveLength(3);
      expect(groups[0].photos).toHaveLength(3);
      expect(groups[1].photos).toHaveLength(3);
      expect(groups[2].photos).toHaveLength(3);
    });

    it('should enforce 30 total photo cap', () => {
      const photos = createMockPhotos(35);
      const groups = photoService.groupPhotosAuto(photos);

      const totalPhotos = groups.reduce((sum, g) => sum + g.photos.length, 0);
      expect(totalPhotos).toBeLessThanOrEqual(30);
    });

    it('should enforce 15 group cap', () => {
      const photos = createMockPhotos(30);
      const groups = photoService.groupPhotosAuto(photos, 1); // 1 photo per group

      expect(groups.length).toBeLessThanOrEqual(15);
    });

    it('should enforce 10 photos per group cap', () => {
      const photos = createMockPhotos(20);
      const groups = photoService.groupPhotosAuto(photos, 15); // Try 15 per group

      groups.forEach(group => {
        expect(group.photos.length).toBeLessThanOrEqual(10);
      });
    });

    it('should set primaryPhotoIndex to 0', () => {
      const photos = createMockPhotos(4);
      const groups = photoService.groupPhotosAuto(photos);

      groups.forEach(group => {
        expect(group.primaryPhotoIndex).toBe(0);
      });
    });

    it('should generate stable groupIds', () => {
      const photos = createMockPhotos(4);
      const groups = photoService.groupPhotosAuto(photos);

      groups.forEach(group => {
        expect(group.groupId).toMatch(/^group_\d+_\d+$/);
      });
    });

    it('should handle empty photo array', () => {
      const groups = photoService.groupPhotosAuto([]);

      expect(groups).toEqual([]);
    });

    it('should handle partial last group', () => {
      const photos = createMockPhotos(5); // 2 per group = 2 groups + 1 leftover
      const groups = photoService.groupPhotosAuto(photos);

      expect(groups).toHaveLength(3);
      expect(groups[2].photos).toHaveLength(1);
    });
  });

  describe('regroupPhotos', () => {
    const createGroups = () => {
      const photos1: PhotoAsset[] = [
        { id: '1', uri: 'file://photo-1.jpg', width: 800, height: 600 },
        { id: '2', uri: 'file://photo-2.jpg', width: 800, height: 600 },
      ];
      const photos2: PhotoAsset[] = [
        { id: '3', uri: 'file://photo-3.jpg', width: 800, height: 600 },
      ];

      return [
        { groupId: 'group-1', photos: photos1, primaryPhotoIndex: 0 },
        { groupId: 'group-2', photos: photos2, primaryPhotoIndex: 0 },
      ];
    };

    it('should move photo from source to target group', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'group-1',
        'file://photo-1.jpg',
        'group-2'
      );

      expect(updated[0].photos).toHaveLength(1);
      expect(updated[1].photos).toHaveLength(2);
      expect(updated[1].photos.some(p => p.uri === 'file://photo-1.jpg')).toBe(true);
    });

    it('should maintain intra-group order', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'group-1',
        'file://photo-1.jpg',
        'group-2'
      );

      // Photo should be added to end of target group
      expect(updated[1].photos[1].uri).toBe('file://photo-1.jpg');
    });

    it('should be immutable (not modify original)', () => {
      const groups = createGroups();
      const originalLength = groups[0].photos.length;

      photoService.regroupPhotos(groups, 'group-1', 'file://photo-1.jpg', 'group-2');

      expect(groups[0].photos).toHaveLength(originalLength);
    });

    it('should be no-op if photo already in target', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'group-1',
        'file://photo-1.jpg',
        'group-1'
      );

      expect(updated).toEqual(groups);
    });

    it('should be no-op if source group not found', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'invalid-group',
        'file://photo-1.jpg',
        'group-2'
      );

      expect(updated).toEqual(groups);
    });

    it('should be no-op if target group not found', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'group-1',
        'file://photo-1.jpg',
        'invalid-group'
      );

      expect(updated).toEqual(groups);
    });

    it('should be no-op if photo not found in source', () => {
      const groups = createGroups();
      const updated = photoService.regroupPhotos(
        groups,
        'group-1',
        'file://nonexistent.jpg',
        'group-2'
      );

      expect(updated).toEqual(groups);
    });

    it('should be no-op if target group is full (10 photos)', () => {
      const fullGroup = {
        groupId: 'group-full',
        photos: Array.from({ length: 10 }, (_, i) => ({
          id: `${i}`,
          uri: `file://photo-${i}.jpg`,
          width: 800,
          height: 600,
        })),
        primaryPhotoIndex: 0,
      };

      const sourceGroup = {
        groupId: 'group-source',
        photos: [{ id: 'x', uri: 'file://extra.jpg', width: 800, height: 600 }],
        primaryPhotoIndex: 0,
      };

      const groups = [sourceGroup, fullGroup];
      const updated = photoService.regroupPhotos(
        groups,
        'group-source',
        'file://extra.jpg',
        'group-full'
      );

      expect(updated).toEqual(groups);
    });
  });
});

/**
 * Unit tests for aiService
 * MODULE-04 LISTING-V3: TASK LISTING-V3-003
 * Tests AI batch analysis, result parsing, and confidence level determination
 */

import * as aiService from '../../services/aiService';
import { AIAnalysisResult } from '../../types/listing';
import { supabase } from '../../config/supabase';

// Mock supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    functions: {
      invoke: jest.fn(),
    },
  },
}));

describe('aiService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('getAIConfidenceLevel', () => {
    it('should return "high" for confidence >= 0.70', () => {
      expect(aiService.getAIConfidenceLevel(0.70)).toBe('high');
      expect(aiService.getAIConfidenceLevel(0.85)).toBe('high');
      expect(aiService.getAIConfidenceLevel(1.00)).toBe('high');
    });

    it('should return "medium" for confidence 0.40-0.69', () => {
      expect(aiService.getAIConfidenceLevel(0.40)).toBe('medium');
      expect(aiService.getAIConfidenceLevel(0.55)).toBe('medium');
      expect(aiService.getAIConfidenceLevel(0.69)).toBe('medium');
    });

    it('should return "low" for confidence < 0.40', () => {
      expect(aiService.getAIConfidenceLevel(0.00)).toBe('low');
      expect(aiService.getAIConfidenceLevel(0.20)).toBe('low');
      expect(aiService.getAIConfidenceLevel(0.39)).toBe('low');
    });
  });

  describe('parseAIResult', () => {
    it('should keep fields with confidence >= 0.40', () => {
      const raw: AIAnalysisResult = {
        title: { value: 'LEGO Dinosaur Set', confidence: 0.85 },
        category: { value: { label: 'Toys', categoryId: '123' }, confidence: 0.70 },
        condition: { value: 'like_new', confidence: 0.50 },
        brand: { value: 'LEGO', confidence: 0.90 },
      };

      const filtered = aiService.parseAIResult(raw);

      expect(filtered.title).toEqual(raw.title);
      expect(filtered.category).toEqual(raw.category);
      expect(filtered.condition).toEqual(raw.condition);
      expect(filtered.brand).toEqual(raw.brand);
    });

    it('should strip fields with confidence < 0.40', () => {
      const raw: AIAnalysisResult = {
        title: { value: 'Toy', confidence: 0.35 },
        category: { value: { label: 'Unknown', categoryId: null }, confidence: 0.25 },
        brand: { value: 'Generic', confidence: 0.10 },
      };

      const filtered = aiService.parseAIResult(raw);

      expect(filtered.title).toBeUndefined();
      expect(filtered.category).toBeUndefined();
      expect(filtered.brand).toBeUndefined();
    });

    it('should preserve rawLabels and error', () => {
      const raw: AIAnalysisResult = {
        rawLabels: ['toy', 'plastic', 'colorful'],
        error: 'Partial analysis failure',
      };

      const filtered = aiService.parseAIResult(raw);

      expect(filtered.rawLabels).toEqual(raw.rawLabels);
      expect(filtered.error).toBe(raw.error);
    });

    it('should handle mix of valid and invalid fields', () => {
      const raw: AIAnalysisResult = {
        title: { value: 'Nike Shoes', confidence: 0.80 }, // Keep
        brand: { value: 'Nike', confidence: 0.30 }, // Strip
        color: { value: ['blue', 'white'], confidence: 0.60 }, // Keep
        age_group: { value: '6-8', confidence: 0.25 }, // Strip
      };

      const filtered = aiService.parseAIResult(raw);

      expect(filtered.title).toBeDefined();
      expect(filtered.brand).toBeUndefined();
      expect(filtered.color).toBeDefined();
      expect(filtered.age_group).toBeUndefined();
    });

    it('should handle empty result', () => {
      const raw: AIAnalysisResult = {};
      const filtered = aiService.parseAIResult(raw);

      expect(Object.keys(filtered)).toHaveLength(0);
    });
  });

  describe('analyzePhotosBatch', () => {
    it('should invoke batch-analyze-items edge function', async () => {
      const mockResponse = {
        results: [
          {
            groupId: 'group-1',
            analysis: {
              title: { value: 'Test Item', confidence: 0.85 },
            },
          },
        ],
        totalProcessed: 1,
        totalFailed: 0,
      };

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: mockResponse,
        error: null,
      });

      const items = [
        {
          groupId: 'group-1',
          primaryPhotoUrl: 'https://example.com/photo1.jpg',
          allPhotoUrls: ['https://example.com/photo1.jpg'],
        },
      ];

      const result = await aiService.analyzePhotosBatch(items, 'seller-123');

      expect(supabase.functions.invoke).toHaveBeenCalledWith('batch-analyze-items', {
        body: {
          items,
          sellerId: 'seller-123',
        },
      });

      expect(result.results).toHaveLength(1);
      expect(result.totalProcessed).toBe(1);
      expect(result.totalFailed).toBe(0);
    });

    it('should parse results defensively', async () => {
      const mockResponse = {
        results: [
          {
            groupId: 'group-1',
            analysis: {
              title: { value: 'Item 1', confidence: 0.85 },
              brand: { value: 'Brand', confidence: 0.30 }, // Should be stripped
            },
          },
          {
            groupId: 'group-2',
            error: 'Analysis failed',
          },
        ],
        totalProcessed: 1,
        totalFailed: 1,
      };

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: mockResponse,
        error: null,
      });

      const items = [
        { groupId: 'group-1', primaryPhotoUrl: 'url1', allPhotoUrls: ['url1'] },
        { groupId: 'group-2', primaryPhotoUrl: 'url2', allPhotoUrls: ['url2'] },
      ];

      const result = await aiService.analyzePhotosBatch(items, 'seller-123');

      expect(result.results[0].analysis?.title).toBeDefined();
      expect(result.results[0].analysis?.brand).toBeUndefined(); // Stripped
      expect(result.results[1].error).toBe('Analysis failed');
    });

    it('should handle edge function error', async () => {
      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: null,
        error: { message: 'Network error' },
      });

      const items = [
        { groupId: 'group-1', primaryPhotoUrl: 'url1', allPhotoUrls: ['url1'] },
      ];

      const result = await aiService.analyzePhotosBatch(items, 'seller-123');

      expect(result.totalFailed).toBe(1);
      expect(result.results[0].error).toBeDefined();
    });

    it('should handle missing response data', async () => {
      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: {},
        error: null,
      });

      const items = [
        { groupId: 'group-1', primaryPhotoUrl: 'url1', allPhotoUrls: ['url1'] },
      ];

      const result = await aiService.analyzePhotosBatch(items, 'seller-123');

      expect(result.results).toEqual([]);
      expect(result.totalProcessed).toBe(0);
      expect(result.totalFailed).toBe(0);
    });
  });

  describe('analyzeSinglePhoto', () => {
    it('should analyze single photo using batch wrapper', async () => {
      const mockResponse = {
        results: [
          {
            groupId: 'single',
            analysis: {
              title: { value: 'Test Item', confidence: 0.85 },
            },
          },
        ],
        totalProcessed: 1,
        totalFailed: 0,
      };

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: mockResponse,
        error: null,
      });

      const result = await aiService.analyzeSinglePhoto(
        'https://example.com/photo.jpg',
        'seller-123'
      );

      expect(result).toHaveProperty('title');
      expect((result as AIAnalysisResult).title?.value).toBe('Test Item');
    });

    it('should return error if analysis fails', async () => {
      const mockResponse = {
        results: [
          {
            groupId: 'single',
            error: 'Analysis failed',
          },
        ],
        totalProcessed: 0,
        totalFailed: 1,
      };

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: mockResponse,
        error: null,
      });

      const result = await aiService.analyzeSinglePhoto(
        'https://example.com/photo.jpg',
        'seller-123'
      );

      expect(result).toHaveProperty('error');
      expect((result as any).error).toBe('Analysis failed');
    });

    it('should return error if no result', async () => {
      (supabase.functions.invoke as jest.Mock).mockResolvedValue({
        data: { results: [], totalProcessed: 0, totalFailed: 0 },
        error: null,
      });

      const result = await aiService.analyzeSinglePhoto(
        'https://example.com/photo.jpg',
        'seller-123'
      );

      expect(result).toHaveProperty('error');
      expect((result as any).error).toBe('No analysis result');
    });
  });
});

