      const palette = conditionService.getColorPalette();

      expect(palette).toHaveLength(12);
      expect(palette[0]).toHaveProperty('label');
      expect(palette[0]).toHaveProperty('hex');
      expect(palette[0]).toHaveProperty('searchTerms');
    });
  });

