    it('should return gray for unknown color', () => {
      const hex = conditionService.getColorHex('unknown-color');

      expect(hex).toBe('#808080');
    });
  });

  describe('validateCondition', () => {
    it('should accept valid conditions', () => {
      expect(conditionService.validateCondition('new')).toBe(true);
      expect(conditionService.validateCondition('like_new')).toBe(true);
      expect(conditionService.validateCondition('good')).toBe(true);
      expect(conditionService.validateCondition('fair')).toBe(true);
      expect(conditionService.validateCondition('worn')).toBe(true);
    });

    it('should reject invalid conditions', () => {
      expect(conditionService.validateCondition('poor')).toBe(false); // V2 legacy
      expect(conditionService.validateCondition('excellent')).toBe(false);
      expect(conditionService.validateCondition('unknown' as any)).toBe(false);
    });
  });
});

